CREATE TABLE IF NOT EXISTS `surveys` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `status` TEXT, `type` TEXT, `environmentId` TEXT NOT NULL, `updatedAt` TEXT, `cachedAt` INTEGER NOT NULL, `json` TEXT NOT NULL, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `queued_responses` (`clientUuid` TEXT NOT NULL, `surveyId` TEXT NOT NULL, `environmentId` TEXT NOT NULL, `surveyorId` TEXT, `finished` INTEGER NOT NULL, `language` TEXT, `dataJson` TEXT NOT NULL, `variablesJson` TEXT, `hiddenFieldsJson` TEXT, `autoStampsJson` TEXT, `capturedAt` INTEGER NOT NULL, `attempts` INTEGER NOT NULL, `lastError` TEXT, `syncedAt` INTEGER, `serverResponseId` TEXT, `sendingAt` INTEGER, PRIMARY KEY(`clientUuid`))
CREATE TABLE IF NOT EXISTS `queued_files` (`clientUuid` TEXT NOT NULL, `surveyId` TEXT NOT NULL, `questionId` TEXT NOT NULL, `environmentId` TEXT NOT NULL, `localPath` TEXT NOT NULL, `fileName` TEXT NOT NULL, `mimeType` TEXT NOT NULL, `sizeBytes` INTEGER NOT NULL, `capturedAt` INTEGER NOT NULL, `boundResponseUuid` TEXT, `attempts` INTEGER NOT NULL, `lastError` TEXT, `uploadedFileUrl` TEXT, `uploadedAt` INTEGER, PRIMARY KEY(`clientUuid`))